// Bundles the referee fixture projects (+ their asset files) and a few import fixtures into
// src/lib/selftest/fixtures.generated.ts for the on-device engine self-test (V1_PLAN P4 step 3), with the hashes of the
// PDFs NODE writes for them (bytes and geometryHash). The self-test writes the same projects on Hermes and compares:
// equal geometry hash = Hermes drew what the referee measured with CoreGraphics (to 1e-6 pt; libm last-bit noise aside). Also cross-checks Node's bytes against artifacts/referee/*.pdf.
// Usage: node --import ./scripts/referee/register.mjs scripts/fixtures/make-selftest-bundle.mjs   (after npm run referee)
import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { inspectAsset, planAssetOf } from '../../src/import/assets.ts';
import { fixtureProjectPdf, geometryHash, hashBytes } from '../../src/lib/selftest/project-pdf.ts';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const FIX = path.join(ROOT, 'test/fixtures');
const files = {};
const read = (rel, base = FIX) => {
  if (!(rel in files)) files[rel] = new Uint8Array(readFileSync(path.join(base, rel)));
  return files[rel];
};

const projects = [];
const expected = {};
for (const name of readdirSync(path.join(FIX, 'projects')).filter((f) => f.endsWith('.json')).sort()) {
  const f = JSON.parse(readFileSync(path.join(FIX, 'projects', name), 'utf8'));
  delete f.expect;
  delete f.about;
  const r = await fixtureProjectPdf(f, (p) => read(p));
  const ref = path.join(ROOT, 'artifacts/referee', `${f.name}.pdf`);
  const refHash = existsSync(ref) ? hashBytes(new Uint8Array(readFileSync(ref))) : null;
  const hash = hashBytes(r.bytes);
  console.log(`${f.name}: ${r.plan.pages.length} pages, ${hash}${refHash ? (refHash === hash ? ' = referee PDF' : ` ≠ referee PDF ${refHash}`) : ' (no referee PDF yet)'}`);
  if (refHash && refHash !== hash) process.exitCode = 1;
  projects.push(f);
  expected[f.name] = { hash, geometry: await geometryHash(r.bytes), pages: r.plan.pages.length, notes: r.notes };
}

// import fixtures: natural sizes Node computes (P3 "real-device checks": compare on Hermes)
const imports = {};
for (const [rel, kind, base] of [
  ['svg/inkscape-mm.svg', 'svg', FIX],
  ['svg/illustrator-72.svg', 'svg', FIX],
  ['pdf/rotate90.pdf', 'pdf', FIX],
  ['svg/h04-use-bomb.svg', 'svg', path.join(ROOT, 'test/blind')],
]) {
  const bytes = read(rel, base);
  const r = await inspectAsset(kind, bytes);
  imports[rel] = r.ok ? { ok: true, kind, plan: planAssetOf({ id: 1, kind, pxW: r.asset.pxW, pxH: r.asset.pxH, svgPxPerIn: null, report: r.asset.report }) } : { ok: false, kind, error: r.error };
  console.log(`${rel}: ${JSON.stringify(imports[rel])}`);
}

const b64 = Object.fromEntries(Object.entries(files).map(([k, v]) => [k, Buffer.from(v).toString('base64')]));
const out = `// GENERATED by scripts/fixtures/make-selftest-bundle.mjs — do not edit. Referee fixture projects, their files
// (base64) and what Node computes for them; the on-device self-test compares Hermes against these.
export const PROJECTS: any[] = ${JSON.stringify(projects)};
export const FILES: Record<string, string> = ${JSON.stringify(b64)};
export const EXPECTED: Record<string, { hash: string; geometry: string; pages: number; notes: number }> = ${JSON.stringify(expected)};
export const IMPORTS: Record<string, any> = ${JSON.stringify(imports)};
`;
writeFileSync(path.join(ROOT, 'src/lib/selftest/fixtures.generated.ts'), out);
console.log(`wrote src/lib/selftest/fixtures.generated.ts (${(out.length / 1024).toFixed(0)} KB)`);
